/*
 * proc1/test/test_proc1_data.c - the PROC1_ module data block (source-l2yd)
 *
 * Generated by: Claude Opus 5.5
 *
 * proc1/proc1_data.c is #included, so the object under test is the real
 * block:
 *
 *   PROC1_$DATA  map "D E254E8 PROC1_ size = CC4"
 *
 * Checked: the image address; the offsets that hold on every build (the
 * absolute ones past ts_elem are asserted at compile time on the target
 * only, because time_queue_elem_t pads to 0x1C on a host); the bias arms
 * (ts_elem[0] over loadav_elem, stats[0] over os_stack_base[62..64] and
 * the pad, type[0] over the low word of stack_low_water); that pid N lands
 * where the assembly's `A5 + base + pid*stride' puts it, relative to the
 * cell the arm is laid against; the zero initial contents; and - through
 * the real PROC1_$SET_TYPE / PROC1_$GET_TYPE / PROC1_$FREE_STACK - that the
 * code indexes the tables with the pid and keeps the stack cells as VAs.
 */

#include <stdint.h>
#include <stdio.h>
#include <string.h>

/* ==========================================================================
 * Test framework
 * ========================================================================== */

static int tests_failed = 0;
static int tests_run = 0;

#define TEST(name) static void test_##name(void)
#define RUN_TEST(name)                                                        \
    do {                                                                      \
        printf("  Running %s... ", #name);                                    \
        tests_run++;                                                          \
        test_##name();                                                        \
        printf("done\n");                                                     \
    } while (0)

#define ASSERT_EQ(expected, actual)                                           \
    do {                                                                      \
        long long _e = (long long)(expected);                                 \
        long long _a = (long long)(actual);                                   \
        if (_e != _a) {                                                       \
            printf("FAILED\n    Expected: 0x%llx, Got: 0x%llx at line %d\n",  \
                   (unsigned long long)_e, (unsigned long long)_a, __LINE__); \
            tests_failed++;                                                   \
            return;                                                           \
        }                                                                     \
    } while (0)

#include "proc1/proc1_internal.h"
#include "misc/misc.h"

/* ==========================================================================
 * Mocked callees
 * ========================================================================== */

static int crashes;
static const status_$t *crash_status;

void CRASH_SYSTEM(const status_$t *status_p)
{
    crashes++;
    crash_status = status_p;
}

/* ==========================================================================
 * Code under test
 * ========================================================================== */

#include "../proc1_data.c"
#include "../set_type.c"
#include "../get_type.c"
#include "../free_stack.c"

/* Byte distance between two cells of the block. */
#define GAP(a, b) ((long long)((const char *)&(b) - (const char *)&(a)))

/* A5 displacements of the tables, from the instructions cited in
 * proc1/proc1.h. */
#define A5_LOADAV_ELEM   0x010
#define A5_TS_ELEM       0x014          /* (0x14,A5,pid*0x1C) */
#define A5_OS_STACK_BASE 0x730          /* (0x730,A5 + pid*4) */
#define A5_STATS         0x828          /* (0x828,A5 + pid*0x10) */
#define A5_STACK_FREE    0xC38
#define A5_STACK_LOW     0xC40
#define A5_TYPE          0xC42          /* (0xc42,A5 + pid*2) */

TEST(block_address_and_size)
{
    ASSERT_EQ(0x00E254E8u, MODULE_DATA_ADDR(PROC1_$DATA));
    ASSERT_EQ(0xCC4, PROC1_$DATA_SIZE);
    /* map symbols inside the block */
    ASSERT_EQ(0x00E25C18u, MODULE_DATA_ADDR(PROC1_$DATA) + A5_OS_STACK_BASE);
    ASSERT_EQ(0x00E25D20u, MODULE_DATA_ADDR(PROC1_$DATA) + A5_STATS + 1 * 0x10);
    ASSERT_EQ(0x00E2612Cu, MODULE_DATA_ADDR(PROC1_$DATA) + A5_TYPE + 1 * 2);
    /* type[64] ends the block, where RING_WIRED begins */
    ASSERT_EQ(0x00E261ACu, MODULE_DATA_ADDR(PROC1_$DATA) + A5_TYPE + 65 * 2);
}

TEST(offsets_every_build)
{
    ASSERT_EQ(0x000, offsetof(proc1_$data_t, loadav));
    ASSERT_EQ(0x010, offsetof(proc1_$data_t, loadav_elem));
    ASSERT_EQ(0x014, offsetof(proc1_$data_t, ts_elem));
    ASSERT_EQ(PROC1_MAX_PROCESSES, sizeof(PROC1_$DATA.ts_elem) / sizeof(PROC1_$DATA.ts_elem[0]));
    ASSERT_EQ(PROC1_MAX_PROCESSES, sizeof(PROC1_$DATA.os_stack_base) / 4);
    ASSERT_EQ(PROC1_MAX_PROCESSES, sizeof(PROC1_$DATA.stats) / 0x10);
    ASSERT_EQ(PROC1_MAX_PROCESSES, sizeof(PROC1_$DATA.type) / 2);
    ASSERT_EQ(PROC1_MAX_PROCESSES, sizeof(PCBS) / sizeof(PCBS[0]));
}

TEST(bias_arms_overlay_the_previous_cells)
{
    /* ts_elem[0] (A5+0x14) sits 4 bytes into loadav_elem (A5+0x10) */
    ASSERT_EQ(A5_TS_ELEM - A5_LOADAV_ELEM,
              GAP(PROC1_$DATA.loadav_elem, PROC1_$DATA.ts_elem[0]));
    /* stats[0] (A5+0x828) is os_stack_base[62]; its last word is the pad */
    ASSERT_EQ(A5_STATS - A5_OS_STACK_BASE,
              GAP(PROC1_$DATA.os_stack_base[0], PROC1_$DATA.stats[0]));
    ASSERT_EQ((uintptr_t)&PROC1_$DATA.os_stack_base[62],
              (uintptr_t)&PROC1_$DATA.stats[0].stat[0]);
    ASSERT_EQ((uintptr_t)&PROC1_$DATA._0834,
              (uintptr_t)&PROC1_$DATA.stats[0].stat[3]);
    /* type[0] (A5+0xC42) is the low word of stack_low_water (A5+0xC40) */
    ASSERT_EQ(A5_TYPE - A5_STACK_LOW,
              GAP(PROC1_$DATA.stack_low_water, PROC1_$DATA.type[0]));
    ASSERT_EQ(A5_STACK_LOW - A5_STACK_FREE,
              GAP(PROC1_$DATA.stack_free_list, PROC1_$DATA.stack_low_water));
}

TEST(pid_n_is_element_n)
{
    unsigned pid;

    for (pid = 0; pid < PROC1_MAX_PROCESSES; pid++) {
        /* (0x730,A5 + pid*4) relative to OS_STACK_BASE */
        ASSERT_EQ((long long)pid * 4,
                  GAP(PROC1_$DATA.os_stack_base[0], PROC1_$DATA.os_stack_base[pid]));
        /* (0x828,A5 + pid*0x10), laid against os_stack_base */
        ASSERT_EQ(A5_STATS + (long long)pid * 0x10 - A5_OS_STACK_BASE,
                  GAP(PROC1_$DATA.os_stack_base[0], PROC1_$DATA.stats[pid]));
        /* (0xC42,A5 + pid*2), laid against stack_free_list */
        ASSERT_EQ(A5_TYPE + (long long)pid * 2 - A5_STACK_FREE,
                  GAP(PROC1_$DATA.stack_free_list, PROC1_$DATA.type[pid]));
        /* (0x14,A5 + pid*0x1C): the stride is the slot's size, 0x1C on the
         * target (asserted there) */
        ASSERT_EQ((long long)pid * (long long)sizeof(proc1_ts_slot_t),
                  GAP(PROC1_$DATA.ts_elem[0], PROC1_$DATA.ts_elem[pid]));
        /* PCBS: 0xE1EACC + pid*4 on the target, one pointer per pid here */
        ASSERT_EQ((long long)pid * (long long)sizeof(PCBS[0]),
                  GAP(PCBS[0], PCBS[pid]));
    }
}

TEST(initial_contents)
{
    static const uint8_t zero[sizeof(proc1_$data_t)];
    ASSERT_EQ(0, memcmp(&PROC1_$DATA, zero, sizeof(PROC1_$DATA)));

    /* PROC1_ASM cells: PROC1_$SUSPEND_EC ships self-linked (image 0xE205F6:
     * 00000000 00e205f6 00e205f6), PROC1_$TSVV as its 18 words */
    ASSERT_EQ(0, PROC1_$SUSPEND_EC.value);
    ASSERT_EQ((uintptr_t)&PROC1_$SUSPEND_EC, (uintptr_t)PROC1_$SUSPEND_EC.waiter_list_head);
    ASSERT_EQ((uintptr_t)&PROC1_$SUSPEND_EC, (uintptr_t)PROC1_$SUSPEND_EC.waiter_list_tail);
    ASSERT_EQ(-1, PROC1_$TSVV[0]);
    ASSERT_EQ(0x7D00, PROC1_$TSVV[7]);
    ASSERT_EQ(0x30D4, PROC1_$TSVV[11]);
    ASSERT_EQ(-1, PROC1_$TSVV[17]);
}

TEST(set_and_get_type_index_with_the_pid)
{
    uint16_t t = 0;

    memset(PROC1_$DATA.type, 0, sizeof(PROC1_$DATA.type));
    crashes = 0;

    PROC1_$SET_TYPE(1, 0x0009);
    PROC1_$SET_TYPE(64, 0x0005);
    ASSERT_EQ(0x0009, PROC1_$DATA.type[1]);         /* map PROC1_$TYPE */
    ASSERT_EQ(0x0005, PROC1_$DATA.type[64]);        /* last word of the block */
    ASSERT_EQ(0, PROC1_$DATA.type[0]);              /* bias slot untouched */
    ASSERT_EQ(0, PROC1_$DATA.type[2]);
    ASSERT_EQ(0, crashes);

    PROC1_$GET_TYPE(64, &t);
    ASSERT_EQ(0x0005, t);
    PROC1_$GET_TYPE(1, &t);
    ASSERT_EQ(0x0009, t);

    /* pid 0 and 0x41 are refused (0x00E152FA / 0x00E15336) */
    PROC1_$SET_TYPE(0, 1);
    ASSERT_EQ(1, crashes);
    ASSERT_EQ((uintptr_t)&Illegal_process_id_err, (uintptr_t)crash_status);
}

TEST(free_stack_threads_vas_through_the_block)
{
    static uint32_t arena[0x800];               /* VA 0 .. 0x2000 */
    uintptr_t saved = ARCH_HOST_VA_BASE;

    ARCH_HOST_VA_BASE = (uintptr_t)arena;
    PROC1_$DATA.stack_high_water = 0x1000;
    PROC1_$DATA.stack_free_list = 0;

    /* at or below the high water mark: not listed (0x00E1512A bls) */
    PROC1_$FREE_STACK(ARCH_VA_TO_PTR(0x1000));
    ASSERT_EQ(0, PROC1_$DATA.stack_free_list);

    /* above it: the link word is the stack top - 4, holding the old head */
    PROC1_$FREE_STACK(ARCH_VA_TO_PTR(0x1800));
    ASSERT_EQ(0x17FC, PROC1_$DATA.stack_free_list);
    ASSERT_EQ(0, arena[0x17FC / 4]);
    PROC1_$FREE_STACK(ARCH_VA_TO_PTR(0x1C00));
    ASSERT_EQ(0x1BFC, PROC1_$DATA.stack_free_list);
    ASSERT_EQ(0x17FC, arena[0x1BFC / 4]);

    PROC1_$DATA.stack_free_list = 0;
    PROC1_$DATA.stack_high_water = 0;
    ARCH_HOST_VA_BASE = saved;
}

int main(void)
{
    printf("PROC1 module data tests\n");
    RUN_TEST(block_address_and_size);
    RUN_TEST(offsets_every_build);
    RUN_TEST(bias_arms_overlay_the_previous_cells);
    RUN_TEST(pid_n_is_element_n);
    RUN_TEST(initial_contents);
    RUN_TEST(set_and_get_type_index_with_the_pid);
    RUN_TEST(free_stack_threads_vas_through_the_block);
    printf("%d tests, %d failed\n", tests_run, tests_failed);
    return tests_failed ? 1 : 0;
}
